// add one per line: date 'yyyy-MM-dd'; repeat 'once' (that date), 'monthly' (its day) or 'yearly' (its day and month)
const reminders = [
  { date: '2028-01-13', repeat: 'once', text: 'Eweka renews on 2028-02-13 at 71.88/yr: ask for a cheaper renewal' },
];
const today = $now.toFormat('yyyy-MM-dd');
const due = {
  once: r => r.date === today,
  monthly: r => r.date.slice(8) === today.slice(8),
  yearly: r => r.date.slice(5) === today.slice(5),
};
return reminders.filter(r => due[r.repeat](r)).map(r => ({ json: r }));
